                '/' => Some(self.scan_symbol()),
                '^' => Some(self.scan_symbol()),
                '%' => Some(self.scan_symbol()),
                '?' => Some(self.scan_symbol()),
                ',' => Some(self.scan_symbol()),
                ';' => Some(self.scan_symbol()),
                '(' => Some(self.scan_symbol()),
                ')' => Some(self.scan_symbol()),
                c if c.is_whitespace() => {
                    self.skip_whitespace();
                    self.scan()
                }
