                num.push(c);
                self.chars.next();
                if let Some(&c) = self.chars.peek() {
                    if c == '+' || c == '-' {
                        num.push(c);
                        self.chars.next();
                    }
                }
                while let Some(&c) = self.chars.peek() {
                    if c.is_ascii_digit() {
                        num.push(c);
                        self.chars.next();
                    } else {
                        break;
                    }
                }
            }
        }

