                Some('\'') => {
                    if self.next_is('\'') {
                        s.push('\'');
                    } else {
                        return Ok(Some(Token::String(s)));
                    }
                }
                Some('\\') => {
                    match self.chars.next() {
                        Some('n') => s.push('\n'),
                        Some('t') => s.push('\t'),
                        Some('\\') => s.push('\\'),
                        Some('\'') => s.push('\''),
                        Some(c) => {
                            s.push('\\');
                            s.push(c);
                        }
                        None => return errinput!("unterminated string escape"),
                    }
                }
                Some(c) => s.push(c),
                None => return errinput!("unterminated string"),
            }
        }
    }

    /// Scans the next symbol token, if any.
    fn scan_symbol(&mut self) -> Token {
        match self.chars.next().unwrap() {
            '.' => Token::Period,
            '=' => Token::Equal,
            '!' => Token::NotEqual,
            '>' => Token::GreaterThan,
            '<' => Token::LessThan,
            '+' => Token::Plus,
            '-' => Token::Minus,
            '*' => Token::Asterisk,
            '/' => Token::Slash,
            '^' => Token::Caret,
            '%' => Token::Percent,
            '?' => Token::Question,
            ',' => Token::Comma,
            ';' => Token::Semicolon,
            '(' => Token::OpenParen,
            ')' => Token::CloseParen,
            _ => panic!("unexpected symbol"),
        }
    }

    /// Skips any whitespace.
    fn skip_whitespace(&mut self) {
        while let Some(&c) = self.chars.peek() {
            if c.is_whitespace() {
                self.chars.next();
            } else {
                break;
            }
        }
    }
}

/// Returns true if the entire given string is a single valid identifier.
pub fn is_ident(ident: &str) -> bool {
    if ident.is_empty() {
        return false;
    }
    let mut chars = ident.chars();
    let first = chars.next().unwrap();
    if !first.is_alphabetic() && first != '_' {
        return false;
    }
    chars.all(|c| c.is_alphanumeric() || c == '_')
}
