/// The lexer (lexical analyzer) preprocesses raw SQL strings into a sequence of
/// lexical tokens (e.g. keyword, number, string, etc), which are passed on to
/// the SQL parser. In doing so, it strips away basic syntactic noise such as
/// whitespace, case, and quotes, and performs initial symbol validation.
pub struct Lexer<'a> {
    chars: Peekable<Chars<'a>>,
}

/// The lexer is used as a token iterator.
impl Iterator for Lexer<'_> {
    type Item = Result<Token>;

    fn next(&mut self) -> Option<Result<Token>> {
        self.scan().transpose()
    }
}

impl<'a> Lexer<'a> {
    /// Creates a new lexer for the given string.
    pub fn new(input: &'a str) -> Lexer<'a> {
        Self { chars: input.chars().peekable() }
    }

    /// Returns the next character if it satisfies the predicate.
    fn next_if(&mut self, predicate: impl Fn(char) -> bool) -> Option<char> {
        self.chars.next_if(predicate)
    }

    /// Applies a closure to the next character, returning its result and
    /// consuming the next character if it's Some.
    fn next_if_map<T>(&mut self, map: impl Fn(char) -> Option<T>) -> Option<T> {
        self.chars.next_if_map(map)
    }

    /// Returns true if the next character is the given character, consuming it.
    fn next_is(&mut self, c: char) -> bool {
        self.chars.next_if_eq(&c).is_some()
    }

    /// Scans the next token, if any.
    fn scan(&mut self) -> Result<Option<Token>> {
        self.skip_whitespace();
        Ok(match self.chars.peek() {
            Some(&c) => match c {
                '.' => Some(self.scan_symbol()),
                '=' => Some(self.scan_symbol()),
                '!' => {
                    if self.next_is('<') {
                        Some(Token::NotEqual)
                    } else {
                        Some(self.scan_symbol())
                    }
                }
                '>' => {
                    if self.next_is('=') {
                        Some(Token::GreaterThanOrEqual)
                    } else {
                        Some(Token::GreaterThan)
                    }
                }
                '<' => {
                    if self.next_is('=') {
                        Some(Token::LessThanOrEqual)
                    } else if self.next_is('>') {
                        Some(Token::LessOrGreaterThan)
                    } else {
                        Some(Token::LessThan)
                    }
                }
                '+' => Some(self.scan_symbol()),
                '-' => Some(self.scan_symbol()),
                '*' => Some(self.scan_symbol()),
                '/' => Some(self.scan_symbol()),
                '^' => Some(self.scan_symbol()),
                '%' => Some(self.scan_symbol()),
                '?' => Some(self.scan_symbol()),
                ',' => Some(self.scan_symbol()),
                ';' => Some(self.scan_symbol()),
                '(' => Some(self.scan_symbol()),
                ')' => Some(self.scan_symbol()),
                c if c.is_whitespace() => {
                    self.skip_whitespace();
                    self.scan()
                }
                c if c.is_ascii_digit() || (c == '.' && self.chars.peek().map(|&c| c.is_ascii_digit()).unwrap_or(false)) => {
                    self.scan_number()
                }
                '\'' => self.scan_string()?,
                '"' => self.scan_ident_quoted()?,
                c if c.is_alphabetic() || c == '_' => Some(self.scan_ident_or_keyword()),
                _ => return errinput!("invalid character: {}", c),
            },
            None => None,
        })
    }

    /// Scans the next identifier or keyword, if any. It's converted to
    /// lowercase, by SQL convention.
    fn scan_ident_or_keyword(&mut self) -> Option<Token> {
        let mut ident = String::new();
        ident.push(self.chars.next().unwrap());
        while let Some(&c) = self.chars.peek() {
            if c.is_alphanumeric() || c == '_' {
                ident.push(c);
                self.chars.next();
            } else {
                break;
            }
        }
        match Keyword::try_from(ident.as_str()) {
            Ok(keyword) => Some(Token::Keyword(keyword)),
            Err(_) => Some(Token::Ident(ident)),
        }
    }

    /// Scans the next quoted identifier, if any. Case is preserved.
    fn scan_ident_quoted(&mut self) -> Result<Option<Token>> {
        let mut ident = String::new();
        loop {
            match self.chars.next() {
                Some('"') => {
                    if self.next_is('"') {
                        ident.push('"');
                    } else {
                        return Ok(Some(Token::Ident(ident)));
                    }
                }
                Some(c) => ident.push(c),
                None => return errinput!("unterminated quoted identifier"),
            }
        }
    }

    /// Scans the next number, if any.
    fn scan_number(&mut self) -> Option<Token> {
        let mut num = String::new();

        // Handle negative numbers - they're separate tokens
        if self.chars.peek() == Some(&'-') {
            return None;
        }

        // Integer part
        while let Some(&c) = self.chars.peek() {
            if c.is_ascii_digit() {
                num.push(c);
                self.chars.next();
            } else {
                break;
            }
        }

        // Decimal part
        if self.next_is('.') {
            num.push('.');
            while let Some(&c) = self.chars.peek() {
                if c.is_ascii_digit() {
                    num.push(c);
                    self.chars.next();
                } else {
                    break;
                }
            }
        }

        // Exponent part
        if let Some(&c) = self.chars.peek() {
            if c == 'e' || c == 'E' {
                num.push(c);
                self.chars.next();
                if let Some(&c) = self.chars.peek() {
                    if c == '+' || c == '-' {
                        num.push(c);
                        self.chars.next();
                    }
                }
                while let Some(&c) = self.chars.peek() {
                    if c.is_ascii_digit() {
                        num.push(c);
                        self.chars.next();
                    } else {
                        break;
                    }
                }
            }
        }

        // Check for special values
        if num == "inf" || num == "infinity" {
            return Some(Token::Number("inf".to_string()));
        }
        if num == "nan" {
            return Some(Token::Number("nan".to_string()));
        }

        Some(Token::Number(num))
    }

    /// Scans the next quoted string literal, if any.
    fn scan_string(&mut self) -> Result<Option<Token>> {
        let mut s = String::new();
        loop {
            match self.chars.next() {
                Some('\'') => {
                    if self.next_is('\'') {
                        s.push('\'');
                    } else {
                        return Ok(Some(Token::String(s)));
                    }
                }
                Some('\\') => {
                    match self.chars.next() {
                        Some('n') => s.push('\n'),
                        Some('t') => s.push('\t'),
                        Some('\\') => s.push('\\'),
                        Some('\'') => s.push('\''),
                        Some(c) => {
                            s.push('\\');
                            s.push(c);
                        }
                        None => return errinput!("unterminated string escape"),
                    }
                }
                Some(c) => s.push(c),
                None => return errinput!("unterminated string"),
            }
        }
    }

    /// Scans the next symbol token, if any.
    fn scan_symbol(&mut self) -> Token {
        match self.chars.next().unwrap() {
            '.' => Token::Period,
            '=' => Token::Equal,
            '!' => Token::NotEqual,
            '>' => Token::GreaterThan,
            '<' => Token::LessThan,
            '+' => Token::Plus,
            '-' => Token::Minus,
            '*' => Token::Asterisk,
            '/' => Token::Slash,
            '^' => Token::Caret,
            '%' => Token::Percent,
            '?' => Token::Question,
            ',' => Token::Comma,
            ';' => Token::Semicolon,
            '(' => Token::OpenParen,
            ')' => Token::CloseParen,
            _ => panic!("unexpected symbol"),
        }
    }

    /// Skips any whitespace.
    fn skip_whitespace(&mut self) {
        while let Some(&c) = self.chars.peek() {
            if c.is_whitespace() {
                self.chars.next();
            } else {
                break;
            }
        }
    }
}

/// Returns true if the entire given string is a single valid identifier.
pub fn is_ident(ident: &str) -> bool {
    if ident.is_empty() {
        return false;
    }
    let mut chars = ident.chars();
    let first = chars.next().unwrap();
    if !first.is_alphabetic() && first != '_' {
        return false;
    }
    chars.all(|c| c.is_alphanumeric() || c == '_')
}

