            Keyword::Float => DataType::Float,
            Keyword::String | Keyword::Varchar | Keyword::Text => DataType::String,
            _ => return errinput!("invalid datatype"),
        },
        t => return errinput!("expected datatype, found {}", t),
    };
    let mut primary_key = false;
    let mut nullable = None;
    let mut default = None;
    let mut unique = false;
    let mut index = false;
    let mut references = None;

    loop {
        if let Some(kw) = self.next_if_keyword() {
            match kw {
                Keyword::Primary => {
                    self.expect(Token::Keyword(Keyword::Key))?;
                    primary_key = true;
                }
                Keyword::Not => {
                    self.expect(Token::Keyword(Keyword::Null))?;
                    nullable = Some(false);
                }
                Keyword::Null => {
                    self.expect(Token::Keyword(Keyword::Null))?;
                    nullable = Some(true);
                }
                Keyword::Default => {
                    default = Some(self.parse_expression()?);
                }
                Keyword::Unique => unique = true,
                Keyword::Index => index = true,
                Keyword::References => {
                    references = Some(self.next_ident()?);
                }
                _ => return errinput!("unexpected keyword {}", kw),
            }
        } else {
            break;
        }
    }

    Ok(ast::Column {
        name,
        datatype,
        primary_key,
        nullable,
        default,
        unique,
        index,
        references,
    })
}

